-- Manual sample data only. This file is not a migration and is not run by the app.
-- Replace YOUR_AUTH_USER_UUID with an existing Supabase Authentication user ID.
-- Assumes commutes.id is generated by the database, as required by POST /commutes.
-- Addresses and ETAs are illustrative, not verified Google results.
-- Re-running this INSERT adds another three records.
WITH owner AS (
  SELECT 'YOUR_AUTH_USER_UUID'::uuid AS user_id
), examples (name, origin_address, destination_address, arrival_time,
             days_of_week, arrival_buffer_minutes, estimated_duration_seconds) AS (
  VALUES
    ('Morning Office',
     '601 W Cordova St, Vancouver, BC, Canada',
     '333 Dunsmuir St, Vancouver, BC, Canada',
     TIME '08:45', ARRAY[1,2,3,4,5]::bigint[], 10, 1200),
    ('Evening Study',
     '457 W 8th Ave, Vancouver, BC, Canada',
     '555 Seymour St, Vancouver, BC, Canada',
     TIME '18:30', ARRAY[2,4]::bigint[], 15, 720),
    ('Weekend Library',
     '2901 E Hastings St, Vancouver, BC, Canada',
     '350 W Georgia St, Vancouver, BC, Canada',
     TIME '10:00', ARRAY[6]::bigint[], 5, 1500)
)
INSERT INTO public.commutes (
  user_id, name, origin_address, destination_address, arrival_time,
  days_of_week, arrival_buffer_minutes, travel_mode,
  estimated_duration_seconds, is_active, created_at, updated_at
)
SELECT owner.user_id, examples.name, examples.origin_address,
       examples.destination_address, examples.arrival_time, examples.days_of_week,
       examples.arrival_buffer_minutes, 'drive', examples.estimated_duration_seconds,
       true, now(), now()
FROM owner CROSS JOIN examples;

-- Expected baseline departures:
-- Morning Office: 08:45 - 20 min - 10 min = 08:15 (Mon-Fri)
-- Evening Study: 18:30 - 12 min - 15 min = 18:03 (Tue, Thu)
-- Weekend Library: 10:00 - 25 min - 5 min = 09:30 (Sat)
